    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; cl=[]
                while st:
                    y,x=st.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; cl.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]==g[y][x] and not seen[ny][nx]:
                                st.append((ny,nx))
                out.append((g[i][j],cl))
    return out
def sig(cl):
    ys=[y for y,_ in cl]; xs=[x for _,x in cl]
    h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
    return (h,w,tuple(sorted((y-min(ys),x-min(xs)) for y,x in cl)))
