    chg=[(i,j) for i in range(len(inp)) for j in range(len(inp[0])) if inp[i][j]!=out[i][j]]
    chcomp=[t for t in cs if set(map(tuple,t[1]))==set(chg)][0]
    tgt=out[chg[0][0]][chg[0][1]]
