    u_c=u_cl=None
    for c2,cl2 in cs:
        if cnt[c2]==1: u_c,u_cl=c2,cl2; break
    cy_=[y for y,_ in chcomp[1]]; cx_=[x for _,x in chcomp[1]]
    uy=[y for y,_ in u_cl]; ux=[x for _,x in u_cl]
    print(f'p{p}: chg={chcomp[0]} size={len(chcomp[1])} tgt={tgt}; singleton={u_c} size={len(u_cl)}')
    d=((sum(cy_)/len(cy_)-sum(uy)/len(uy))**2+(sum(cx_)/len(cx_)-sum(ux)/len(ux))**2)**0.5
