    bg=g[0][0]; cs=comps_of(g,bg)
    cnt=Counter(c for c,_ in cs)
    shapes=defaultdict(list)
    for c,cl in cs: shapes[sig(cl)].append((c,cl))
    res=[r[:] for r in g]
