def comps_of(g,bg=None):
    seen=[[False]*len(g[0]) for _ in range(len(g))]
    out=[]
    from collections import deque
    for i in range(len(g)):
        for j in range(len(g[0])):
            if not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); cells=[]
                seen[i][j]=True
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]) and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append((col,cells))
    return out

def sig(cl):
    cy,cx=min(y for y,_ in cl),min(x for _,x in cl)
    s=frozenset((y-cy,x-cx) for y,x in cl)
    # rotate-normalize variant omitted
    return s

def solve(g):
    bg=g[0][0]; cs=comps_of(g,bg)
    cnt=Counter(c for c,_ in cs)
    singles=[c for c in cnt if cnt[c]==1]
    tgt=max(singles,key=lambda c:max(len(cl) for cc,cl in cs if cc==c))
    tcells=[cl for cc,cl in cs if cc==tgt][0]
    tb=(min(y for y,_ in tcells),max(y for y,_ in tcells),min(x for _,x in tcells),max(x for _,x in tcells))
    res=[r[:] for r in g]
    sh=defaultdict(list)
    for c,cl in cs:
        sh[sig(cl)].append((c,cl))
    for key,vv in sh.items():
        if len(vv)<2 or len(set(cc for cc,_ in vv))==1: continue
        ins=[v for v in vv if min(y for y,_ in v[1])>=tb[0] and max(y for y,_ in v[1])<=tb[1] and min(x for _,x in v[1])>=tb[2] and max(x for _,x in v[1])<=tb[3]]
        outs=[v for v in vv if v not in ins]
        if len(ins)==1 and len(outs)>=1:
            for v in outs:
                for y,x in v[1]: res[y][x]=tgt
    return res

